# Repository instructions

- 使用简体中文交流和写文档。
- `src/` 与 `tests/` 是实现源码；规划工作只能修改 `docs/plans/`。
- Node.js CommonJS，测试使用 `node --test`。
- 所有计划路径必须相对仓库根目录。
{
  "name": "order-import-enrichment-fixture",
  "private": true,
  "scripts": {
    "test": "node --test tests/*.test.js"
  }
}

'use strict';

function importOrders(rows, client) {
  return client.send(rows);
}

module.exports = { importOrders };
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { importOrders } = require('../src/order-importer');

test('forwards rows to the client', async () => {
  const rows = [{ id: 'o-1' }];
  const result = await importOrders(rows, { send: async (value) => value });
  assert.deepEqual(result, rows);
});

